import { layoutStaff } from 'app/components/Staff/layout';

import { DEFAULT_BPM, getNoteDuration } from '../MelodiesService/timing';
import type { Melody } from '../MelodiesService/types';
import { MelodyExportError } from './errors';
import { getExportNotes } from './notes';

export const SCORE_WIDTH = 760;
export const PAGE_WIDTH = 595.28;
export const PAGE_HEIGHT = 841.89;
export const PAGE_MARGIN = 36;
export const CONTENT_WIDTH = PAGE_WIDTH - PAGE_MARGIN * 2;
export const SCORE_SCALE = CONTENT_WIDTH / SCORE_WIDTH;
export const SYSTEM_GAP = 12;

export const prepareScoreMelody = (melody: Melody): Melody => {
  getExportNotes(melody);
  if (
    melody.notes.length > 10000 ||
    melody.notes.some(note => note.start + getNoteDuration(note) > 3600000)
  )
    throw new MelodyExportError(
      'PDF supports melodies up to one hour and 10,000 notes. Shorten the melody and export again.',
    );
  return {
    ...melody,
    bpm:
      Number.isFinite(melody.bpm) && melody.bpm! > 0 ? melody.bpm : DEFAULT_BPM,
    notes: melody.notes
      .map(note => ({ ...note, duration: getNoteDuration(note) }))
      .sort((a, b) => a.start - b.start),
  };
};

export const getScoreStaffLines = (melody: Melody) =>
  layoutStaff(melody, melody.bpm!, 0, SCORE_WIDTH);

// Read the renderer's dimensions so PDF pagination follows staff UI changes.
export const getSvgSystem = (markup: string) => {
  const dimensions = /viewBox="0 0 ([\d.]+) ([\d.]+)"/.exec(markup);
  if (!dimensions)
    throw new MelodyExportError('Could not determine staff line dimensions.');
  return {
    markup,
    width: Number(dimensions[1]),
    height: Number(dimensions[2]),
  };
};

// Keep each system intact. Unusually tall systems shrink to fit one page.
export const paginateScore = <T extends { height: number; width?: number }>(
  systems: T[],
  availableHeight: number,
) => {
  const pages: { system: T; height: number }[][] = [];
  let used = 0;
  systems.forEach(system => {
    const height = Math.min(
      (system.height * CONTENT_WIDTH) / (system.width ?? SCORE_WIDTH),
      availableHeight,
    );
    if (!pages.length || used + height > availableHeight) {
      pages.push([]);
      used = 0;
    }
    pages[pages.length - 1].push({ system, height });
    used += height + SYSTEM_GAP;
  });
  if (pages.length > 200)
    throw new MelodyExportError(
      'PDF exceeds 200 pages. Shorten the melody and export again.',
    );
  return pages;
};
