import { renderToStaticMarkup } from 'react-dom/server';
import { ThemeProvider } from 'styled-components';

import {
  formatTabPosition,
  getTablatureFingering,
} from 'app/services/TablatureService/fingering';

import { NoteExpressionMark } from 'app/components/Staff/NoteExpressionMark';
import { StaffLine } from 'app/components/Staff/StaffLine';
import { STRINGS } from 'app/components/Tablature/mappings';
import { StringInstrumentType } from 'app/components/Tablature/types';

import { themes } from 'styles/theme/themes';

import { getTimeSignature } from '../MelodiesService/meter';
import type { Melody } from '../MelodiesService/types';
import { MelodyExportError } from './errors';
import {
  ScoreExportFormat,
  getScoreInstrument,
  scoreFormats,
} from './scoreFormats';
import {
  CONTENT_WIDTH,
  PAGE_HEIGHT,
  PAGE_MARGIN,
  PAGE_WIDTH,
  SCORE_WIDTH,
  SYSTEM_GAP,
  getScoreStaffLines,
  getSvgSystem,
  paginateScore,
  prepareScoreMelody,
} from './scoreLayout';

const TAB_CHUNK_SIZE = 28;
const RENDER_SCALE = 4;

export const getTabSystems = (
  melody: Melody,
  instrument: StringInstrumentType,
  optimize: boolean | 'composition' = false,
) => {
  const strings = STRINGS[instrument];
  const { positions } = getTablatureFingering(
    melody.notes,
    instrument,
    !!optimize,
    optimize === 'composition',
  );
  const systems: { markup: string; width: number; height: number }[] = [];
  for (let start = 0; start < melody.notes.length; start += TAB_CHUNK_SIZE) {
    const notes = melody.notes.slice(start, start + TAB_CHUNK_SIZE);
    const rows = strings.map((_, string) =>
      notes.map((_, index) =>
        formatTabPosition(positions[start + index], string),
      ),
    );
    const expressionHeight = notes.some(note => note.expression) ? 30 : 0;
    const height = 60 + expressionHeight + strings.length * 22;
    systems.push({
      height,
      width: SCORE_WIDTH,
      markup: renderToStaticMarkup(
        <svg viewBox={`0 0 ${SCORE_WIDTH} ${height}`}>
          <text x="0" y="15" fontSize="12">
            Notes {start + 1}-{start + notes.length}
          </text>
          {notes.map((event, index) => (
            <NoteExpressionMark
              key={`expression-${index}`}
              expression={event.expression}
              x={42 + index * 24}
              y={45}
              width={20}
            />
          ))}
          {notes.map((event, index) =>
            rows.every(row => row[index] === '---') ? (
              <text
                key={index}
                x={50 + index * 24}
                y={35 + expressionHeight}
                fontSize="10"
                textAnchor="middle"
              >
                {event.note}
              </text>
            ) : null,
          )}
          {strings.map((string, index) => (
            <g key={string}>
              <text x="0" y={55 + expressionHeight + index * 22} fontSize="12">
                {string}
              </text>
              <line
                x1="35"
                x2="730"
                y1={51 + expressionHeight + index * 22}
                y2={51 + expressionHeight + index * 22}
                stroke="black"
                strokeWidth="0.7"
              />
              {rows[index].map((part, column) =>
                part === '---' ? null : (
                  <g key={column}>
                    <rect
                      x={40 + column * 24}
                      y={40 + expressionHeight + index * 22}
                      width="20"
                      height="20"
                      fill="white"
                    />
                    <text
                      x={50 + column * 24}
                      y={55 + expressionHeight + index * 22}
                      textAnchor="middle"
                      fontSize="13"
                    >
                      {part.replace(/-/g, '')}
                    </text>
                  </g>
                ),
              )}
            </g>
          ))}
        </svg>,
      ),
    });
  }
  return systems;
};

const loadSvgImage = async (markup: string, clef?: string) => {
  const svg = new DOMParser().parseFromString(
    markup,
    'image/svg+xml',
  ).documentElement;
  svg.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
  const [, , width, height] = svg.getAttribute('viewBox')!.split(' ');
  svg.setAttribute('width', width);
  svg.setAttribute('height', height);
  svg.setAttribute('style', 'color: black; fill: black; font-family: Arial');
  svg.querySelectorAll('ellipse').forEach(element => {
    if (element.getAttribute('fill') === 'var(--staff-background)')
      element.setAttribute('fill', 'white');
  });
  if (clef)
    svg.querySelectorAll('image').forEach(element => {
      element.setAttribute(
        'href',
        `data:image/svg+xml;charset=utf-8,${encodeURIComponent(clef)}`,
      );
    });
  const url = URL.createObjectURL(
    new Blob([new XMLSerializer().serializeToString(svg)], {
      type: 'image/svg+xml;charset=utf-8',
    }),
  );
  try {
    return await new Promise<HTMLImageElement>((resolve, reject) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = () =>
        reject(new MelodyExportError('Could not render notes for PDF.'));
      image.src = url;
    });
  } finally {
    URL.revokeObjectURL(url);
  }
};

const wrapText = (
  context: CanvasRenderingContext2D,
  value: string,
  maxLines: number,
) => {
  const lines = [''];
  for (const char of value.replace(/\s+/g, ' ').trim()) {
    const index = lines.length - 1;
    if (context.measureText(lines[index] + char).width > CONTENT_WIDTH) {
      if (lines.length === maxLines) {
        lines[index] = `${lines[index].slice(0, -1)}…`;
        break;
      }
      lines.push(char);
    } else lines[index] += char;
  }
  return lines;
};

export const createScorePdf = async (
  source: Melody,
  format: ScoreExportFormat,
  optimizeTablature: boolean | 'composition' = false,
): Promise<Blob> => {
  const melody = prepareScoreMelody(source);
  const instrument = getScoreInstrument(format);
  const systems = instrument
    ? getTabSystems(melody, instrument, optimizeTablature)
    : getScoreStaffLines(melody).map(line =>
        getSvgSystem(
          renderToStaticMarkup(
            <ThemeProvider theme={themes.light}>
              <StaffLine line={line} bpm={melody.bpm!} />
            </ThemeProvider>,
          ),
        ),
      );
  let clef: string | undefined;
  if (!instrument && systems.some(system => system.markup.includes('<image'))) {
    const response = await fetch(`${process.env.PUBLIC_URL}/clef-g.svg`);
    if (!response.ok)
      throw new MelodyExportError(
        'Could not load the treble clef. Retry the PDF download.',
      );
    clef = await response.text();
  }
  const canvas = document.createElement('canvas');
  canvas.width = Math.ceil(PAGE_WIDTH * RENDER_SCALE);
  canvas.height = Math.ceil(PAGE_HEIGHT * RENDER_SCALE);
  const context = canvas.getContext('2d');
  if (!context)
    throw new MelodyExportError(
      'This browser does not support PDF generation.',
    );
  context.scale(RENDER_SCALE, RENDER_SCALE);
  context.font = '18px Arial';
  const title = wrapText(
    context,
    melody.displayTitle || melody.title || 'Melody Generator recording',
    3,
  );
  context.font = '11px Arial';
  const author = melody.author ? wrapText(context, melody.author, 2) : [];
  const contentTop = PAGE_MARGIN + title.length * 23 + author.length * 16 + 62;
  const pages = paginateScore(
    systems,
    PAGE_HEIGHT - PAGE_MARGIN - 28 - contentTop,
  );
  const { PDFDocument } = await import('pdf-lib');
  const pdf = await PDFDocument.create();
  pdf.setTitle(
    melody.displayTitle || melody.title || 'Melody Generator recording',
  );
  pdf.setAuthor(melody.author || 'Melody Generator');
  pdf.setCreator('Melody Generator');
  try {
    for (let index = 0; index < pages.length; index++) {
      context.fillStyle = 'white';
      context.fillRect(0, 0, PAGE_WIDTH, PAGE_HEIGHT);
      context.fillStyle = 'black';
      context.textBaseline = 'top';
      context.font = '18px Arial';
      let top = PAGE_MARGIN;
      title.forEach(line => {
        context.fillText(line, PAGE_MARGIN, top);
        top += 23;
      });
      context.font = '11px Arial';
      author.forEach(line => {
        context.fillText(line, PAGE_MARGIN, top);
        top += 16;
      });
      context.fillText(
        `${melody.bpm} BPM · ${getTimeSignature(melody.timeSignature)} · ${
          scoreFormats[format].label
        }`,
        PAGE_MARGIN,
        top + 8,
      );
      context.font = '9px Arial';
      const hints = instrument
        ? [
            "Note order and fingering match the app's tabs; durations are omitted.",
            "Labels above the tabs indicate notes outside the instrument's range.",
          ]
        : [
            'Rhythm symbols are approximate, as on the on-screen staff.',
            'Spacing between notes reflects their start times.',
          ];
      hints.forEach((hint, i) =>
        context.fillText(hint, PAGE_MARGIN, top + 27 + i * 13),
      );
      let y = contentTop;
      for (const { system, height } of pages[index]) {
        const image = await loadSvgImage(system.markup, clef);
        const width = Math.min(
          CONTENT_WIDTH,
          (height / system.height) * system.width,
        );
        context.drawImage(image, PAGE_MARGIN, y, width, height);
        y += height + SYSTEM_GAP;
      }
      context.font = '9px Arial';
      context.fillText(
        'Melody Generator',
        PAGE_MARGIN,
        PAGE_HEIGHT - PAGE_MARGIN,
      );
      context.textAlign = 'right';
      context.fillText(
        `${index + 1} / ${pages.length}`,
        PAGE_WIDTH - PAGE_MARGIN,
        PAGE_HEIGHT - PAGE_MARGIN,
      );
      context.textAlign = 'left';
      const png = await new Promise<Blob>((resolve, reject) =>
        canvas.toBlob(blob => {
          if (blob) resolve(blob);
          else
            reject(new MelodyExportError('Could not assemble the PDF page.'));
        }, 'image/png'),
      );
      const image = await pdf.embedPng(await png.arrayBuffer());
      const page = pdf.addPage([PAGE_WIDTH, PAGE_HEIGHT]);
      page.drawImage(image, {
        x: 0,
        y: 0,
        width: PAGE_WIDTH,
        height: PAGE_HEIGHT,
      });
      // Release decoded pixels before rendering the next high-resolution page.
      await image.embed();
    }
    return new Blob([await pdf.save()], { type: 'application/pdf' });
  } finally {
    canvas.width = 0;
    canvas.height = 0;
  }
};
